head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSecugrpID = "";
scwin.clickIsurCd = "";
// 화면 리사이징

scwin.list_dtl_noti_id;
scwin.selBzProcsNo, scwin.selPrtDepoId, scwin.selExerSeq, scwin.selRowPos, scwin.isGongsi = "";
scwin.vIsurCd, scwin.vComNm = "";
scwin.clickBzProcsNo, scwin.clickListProcsStatCd = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.cm.PanelToGroupBox(__GROUPBOX_BACKGROUND__panel_1);
        scwin.setCode();
        $c.cm.fn_com_isur(txb_ISUR_CD, txb_COM_NM);
        btn_Acpt.hide();
        btn_Ret.hide();
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_select_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_select_onclick = async function() {
    try {
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.btn_select_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF41610.xml", SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewOffice(grd_Grid, "파이프라인 진행 경과", "", 1, 0);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Close_onclick = function() {
    try {
        self.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        // txb_TotCnt.value = "총 " + rowcount + "건";
        if (rowcount <= 0) {
            dts_List.removeAll();
        }
        scwin.setRcvRetButtonFalse(); // 접수,반려 버튼 안보이게
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_Grid_OnDblClick
 * @description grd_Grid 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_Grid_OnDblClick = async function(row, colid) {
    try {
        if (row > 0) {
            // 그리드에서 선택시
            scwin.setBzProcsNo(row);
        }
        if ("34" === scwin.clickListProcsStatCd) {
            // 수정요청 리스트 팝업창
            const adjreqUrl = "/lstmgt/ULDSTF41611.gfm";
            await $c.frame.CreateDialogFrame("ULDSTF41611.gfm", adjreqUrl, "기술성장기업 상장이후 성과분석 수정요청 리스트", 50, 50, 750, 300, "window");
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.grd_Grid_OnDblClick" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onkeyup
 * @description txb_ISUR_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onkeyup = function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.txb_ISUR_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onfocus
 * @description txb_ISUR_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.txb_ISUR_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISUR_CD_onblur
 * @description txb_ISUR_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISUR_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISUR_CD.getValue() === "") {
            txb_COM_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.txb_ISUR_CD_onblur" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        $c.cm.IsurcdSearch(txb_ISUR_CD, txb_COM_NM);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name btn_Acpt_onclick
 * @description 「접수」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Acpt_onclick = async function() {
    try {
        await scwin.receive("33");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.btn_Acpt_onclick" });
    }
};

/**
 * @method
 * @name btn_Ret_onclick
 * @description 「반려」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Ret_onclick = async function() {
    try {
        await scwin.receive("37");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.btn_Ret_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S1');
        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF41610.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.cmb_PeriodTp_onselchange" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name grd_Grid_OnClick
 * @description grd_Grid 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_Grid_OnClick = function(row, colid) {
    try {
        // alert('grd_Grid.OnClick('+row+','+ colid+')');
        // 처리상태 제출완료 인 경우 접수, 반려 버튼 활성
        if (row > 0) {
            // 그리드에서 선택시
            scwin.setBzProcsNo(row);
        }
        if ("32" === scwin.clickListProcsStatCd) {
            // 접수,반려 버튼 활성화
            btn_Acpt.show("");
            btn_Ret.show("");
            // btn_Acpt.disabled = false;
            // btn_Ret.disabled = false;

        } else {
            btn_Acpt.hide();
            btn_Ret.hide();
            // btn_Acpt.disabled = true;
            // btn_Ret.disabled = true;

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF41610.grd_Grid_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    /*
        // 회사 선택
		if (txb_ISUR_CD.value == "") {
			alert("[회사]를 선택해주세요.");
			txb_ISUR_CD.focus();
			return;
		}
     */
    const ISUR_CD = txb_ISUR_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name receive
 * @description receive 처리
 * @param {*} type type
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.receive = async function(type) {
    let typeString = "";
    if (type === "33") typeString = "접수";

    else typeString = "반려";
    const vAnswer = confirm("선택된 항목을 모두 " + typeString + "처리 하시겠습니까?");
    if (vAnswer) {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     TRS_IDX : "U",
        //     LIST_BZ_TP_CD : "800",
        //     LIST_PROCS_STAT_CD : type,
        //     PIPE_BZ_PROCS_NO : scwin.clickBzProcsNo,
        //     PIPE_ISUR_CD : scwin.clickIsurCd,
        //     PROCS_EMP_NO : js_emp_no
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/SkilGrowthComAFListOutcome.do",
            ref : "dts_List",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setCode
 * @description 기간 from~ to  셋팅
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    //  기간 from~ to  셋팅
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDate.setValue($c.ut.cGetMinusDate2(vCurDate, 365)); // 일년 날짜
    edt_EDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜

    $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
};

/**
 * @method
 * @name getPar
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getPar = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.vSecugrpID; // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setPar
 * @description 2010.04.20 회사코드 추가
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.setPar = function(arrPar) {
    txb_COM_NM.setValue(arrPar[0].COM_NM);
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
};

/**
 * @method
 * @name setBzProcsNo
 * @description set Bz Procs No 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setBzProcsNo = function(obj) {
    scwin.clickIsurCd = dts_List.getCellData(Number(obj), "ISUR_CD");
    scwin.clickBzProcsNo = dts_List.getCellData(Number(obj), "PIPE_BZ_PROCS_NO");
    scwin.clickListProcsStatCd = dts_List.getCellData(Number(obj), "PIPE_LIST_PROCS_STAT_CD");
};

/**
 * @method
 * @name setRcvRetButtonFalse
 * @description set Rcv Ret Button False 처리
 * @returns {void}
 * @hidden N
 */
scwin.setRcvRetButtonFalse = function() {
    btn_Acpt.hide();
    btn_Ret.hide();
};
